head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setHeaderSortImage]<br/>Header Column 의 ID 를 사용하여 특정 Header Column 에 정렬 상태 아이콘을 설정합니다. 실제 데이터 정렬은 실행되지 않으며 정렬 상태 아이콘만 설정합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 정렬 상태 아이콘을 설정할 Header Column 의 ID 를 설정할 수 있어야 합니다.",
        "존재하지 않는 headerId 를 설정하면 정렬 상태 아이콘이 설정되지 않습니다.",
        "order(선택) 파라미터값이 1 이면 오름차순 정렬 상태 아이콘을 설정하며 'w2grid_head_sort_asc' CSS 클래스가 적용됩니다.",
        "order(선택) 파라미터값이 -1 이면 내림차순 정렬 상태 아이콘을 설정하며 'w2grid_head_sort_desc' CSS 클래스가 적용됩니다.",
        "order(선택) 파라미터값이 0 이면 정렬 없음 상태 아이콘을 설정하며 showSortableImage=true, sortable=true 인 경우 'w2grid_head_sort_none' CSS 클래스가 적용됩니다.",
        "order(선택) 파라미터를 생략하면 기본값으로 동작합니다.",
        "sortable, hideSortIconOnNoData, showSortableImage 속성과 관계없이 setHeaderSortImage() 메소드로 정렬 상태 아이콘을 설정할 수 있습니다.",
        "sortable=true 인 Header Column 인 경우 showSortableImage=true 면 order 파라미터값에 따라 th 요소의 aria-sort 속성에 'ascending', 'descending', 'other' 값이 설정됩니다.",
        "order 파라미터값이 0 일때 showSortableImage=false 이면 정렬 상태 아이콘이 표시되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    //  - con_sortable / con_showSortableImage 가 미설정('') 이면 createCList 가 빈 문자열 value 를 자동 제외하여 키가 빠짐(기본값 동작)
    //  - setHeaderSortImage 는 sortable, showSortableImage 속성과 무관하게 동작하나, 0(none) 아이콘 표시 및 aria-sort 검증을 위해 con 옵션으로 조합 확인
    let properties = {
        sortable: con_sortable.getText(),
        showSortableImage: con_showSortableImage.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblSortable = con_sortable.getText() === '' ? '미설정' : con_sortable.getText();
    let lblShowSortableImage = con_showSortableImage.getText() === '' ? '미설정' : con_showSortableImage.getText();
    $c.gcm.createLabel('label="sortable=' + lblSortable + ', showSortableImage=' + lblShowSortableImage + ' 로 GridView 생성 (Header Column ID : column1~column4)"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, '');
}



// 특정 Header Column 의 th 요소 class / aria-sort 를 읽어 정렬 상태 아이콘 적용 결과 출력
scwin.getHeaderState = function (headerId) {
    // th 요소는 [data-header_id='headerId'] 또는 id 에 '_headerId' 포함으로 탐색
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (!headTable) return null;
    let ths = headTable.getElementsByTagName("th");
    for (let i = 0; i < ths.length; i++) {
        if (ths[i].getAttribute("data-header_id") === headerId) {
            return ths[i];
        }
    }
    return null;
};



scwin.btn_setHeaderSortImage_onclick = function () {
    let headerId = par_headerId.getValue();
    let orderVal = par_order.getValue();

    // order(선택) 생략 처리
    let hasOrder = (orderVal !== '');

    if (hasOrder) {
        target1.setHeaderSortImage(headerId, Number(orderVal));
        wf_body_bottom.getObj("scwin").setReturnValue("setHeaderSortImage('" + headerId + "', " + orderVal + ")");
    } else {
        // order 생략 → 기본값 동작
        target1.setHeaderSortImage(headerId);
        wf_body_bottom.getObj("scwin").setReturnValue("setHeaderSortImage('" + headerId + "') - order 생략(기본값)");
    }

    // 설정 결과 확인 : 해당 Header Column 의 th class / aria-sort 출력
    let th = scwin.getHeaderState(headerId);
    if (th === null) {
        wf_body_bottom.getObj("scwin").setReturnValue("→ headerId '" + headerId + "' 에 해당하는 Header Column 이 없어 아이콘이 설정되지 않았습니다.");
        return;
    }

    // 정렬 상태 아이콘 클래스는 th 하위 정렬 영역(table td / div / button)에 적용됨 → th 전체 영역에서 클래스 존재 여부 확인
    let asc = th.querySelector(".w2grid_head_sort_asc") ? "w2grid_head_sort_asc" : "";
    let desc = th.querySelector(".w2grid_head_sort_desc") ? "w2grid_head_sort_desc" : "";
    let none = th.querySelector(".w2grid_head_sort_none") ? "w2grid_head_sort_none" : "";
    let imageNone = th.querySelector(".w2grid_head_sort_image_none") ? "w2grid_head_sort_image_none" : "";
    let sortClass = asc || desc || none || imageNone || "(정렬 아이콘 클래스 없음)";

    wf_body_bottom.getObj("scwin").setReturnValue("→ 적용된 정렬 상태 아이콘 클래스 : " + sortClass);

    // sortable=true 인 경우 aria-sort 속성 출력
    let ariaSort = th.getAttribute("aria-sort");
    wf_body_bottom.getObj("scwin").setReturnValue("→ th aria-sort 속성 : " + (ariaSort === null ? "(미설정)" : ariaSort));
};
